package cn.privatereader

import org.junit.Test
import org.junit.Assert.*
import java.nio.file.Files

class StoryModelTest {
 @Test fun repeatedPassageUsesExactOffsets(){val c=Chapter("章","他说再见。她说再见。");val a=selectionAnchor(c,7,9);val edited=applyAnchoredEdit(c,a,"你好",emptyList());assertEquals("他说再见。她说你好。",edited.text);assertEquals(c.id,edited.id);assertEquals(c.revision+1,edited.revision)}
 @Test fun staleCandidateRejectedEvenWhenTextReappears(){val c=Chapter("章","再见");val a=selectionAnchor(c,0,2);assertThrows(IllegalArgumentException::class.java){applyAnchoredEdit(c.copy(revision=2),a,"你好",emptyList())};assertThrows(IllegalArgumentException::class.java){applyAnchoredEdit(c.copy(id=newId()),a,"你好",emptyList())}}
 @Test fun unicodeAndProtection(){val c=Chapter("章","😀名字名字");assertThrows(IllegalArgumentException::class.java){selectionAnchor(c,1,2)};val a=selectionAnchor(c,2,6);assertThrows(IllegalArgumentException::class.java){applyAnchoredEdit(c,a,"名字",listOf("名字"))};assertEquals("😀称呼",applyAnchoredEdit(c,a,"称呼",emptyList()).text)}
 @Test fun structuredDataSurvivesBackupAndNamesAreNotKeys(){val root=Files.createTempDirectory("story-model").toFile();try{val s=Store(root);val b=s.importBook("合成.txt","重复重复".toByteArray());val c=b.chapters[0];val a=StoryCard(kind=CardKind.CHARACTER,name="同名",sceneIds=listOf(c.scene.id),source=selectionAnchor(c,2,4));val d=StoryCard(kind=CardKind.CHARACTER,name="同名");val place=StoryCard(kind=CardKind.PLACE,name="码头");val outline=StoryCard(kind=CardKind.OUTLINE,name="相遇",notes="合成大纲");val r=StoryRelation(fromId=a.id,toId=d.id,label="认识",sceneIds=listOf(c.scene.id));val saved=s.save(b.copy(cards=listOf(a,d,place,outline),relations=listOf(r)));val restored=s.importBackup(s.exportBackup(b.id));assertEquals(saved.cards,restored.cards);assertEquals(saved.relations,restored.relations);assertEquals(saved.chapters,restored.chapters);assertNotEquals(a.id,d.id);val edited=s.editSelection(b.id,a.source!!,"更改");assertFalse(a.source.matches(edited.chapters[0]));assertEquals(saved.cards,edited.cards);assertArrayEquals("重复重复".toByteArray(),s.originalBytes(b.id))}finally{root.deleteRecursively()}}
 @Test fun atomicApplyRejectsChangedStoredVersionAndUndoDoesNotOverwrite(){val root=Files.createTempDirectory("story-atomic").toFile();try{val s=Store(root);val b=s.importBook("合成.txt","旧句旧句".toByteArray());val c=b.chapters[0];val a=selectionAnchor(c,2,4);val first=s.editSelection(b.id,a,"新句");assertThrows(IllegalArgumentException::class.java){s.editSelection(b.id,a,"过期")};val restored=s.undoSelection(b.id,c,first.chapters[0]);assertEquals(c.text,restored.chapters[0].text);assertTrue(restored.chapters[0].revision>first.chapters[0].revision);assertThrows(IllegalArgumentException::class.java){s.undoSelection(b.id,c,first.chapters[0])};assertThrows(IllegalArgumentException::class.java){s.editSelection(b.id,a,"过期")}}finally{root.deleteRecursively()}}
 @Test fun invalidRelationshipRejected(){val root=Files.createTempDirectory("story-relation").toFile();try{val s=Store(root);val b=s.importBook("合成.txt","文字".toByteArray());assertThrows(IllegalArgumentException::class.java){s.save(b.copy(relations=listOf(StoryRelation(fromId="missing",toId="other",label="认识"))))}}finally{root.deleteRecursively()}}
 @Test fun legacyVersionOneGetsStableIdsWithoutGuessingFacts(){val root=Files.createTempDirectory("story-legacy").toFile();try{val s=Store(root);val b=s.importBook("旧备份.txt","原文".toByteArray());val file=java.io.File(root,"${b.id}/book.json");val j=org.json.JSONObject(file.readText());j.remove("cards");j.remove("relations");j.put("facts","旧人物说明");val c=j.getJSONArray("chapters").getJSONObject(0);listOf("id","revision","sceneId","sceneTitle","epoch").forEach{c.remove(it)};file.writeText(j.toString());val first=s.load(b.id)!!;assertEquals(first,s.load(b.id));assertTrue(first.cards.isEmpty());assertEquals("旧人物说明",first.facts);assertEquals("chapter-0",first.chapters[0].id);assertEquals("scene-0",first.chapters[0].scene.id);val restored=s.importBackup(s.exportBackup(b.id));assertEquals(first.chapters,restored.chapters);assertEquals(first.facts,restored.facts)}finally{root.deleteRecursively()}}
 @Test fun promptScopeUsesIdsAndNeverTraversesFutureScene(){val c=Chapter("当前","前文选区后文");val future=Chapter("未来","未来正文秘密");val a=StoryCard(kind=CardKind.CHARACTER,name="同名",notes="当前资料一",sceneIds=listOf(c.scene.id));val b=StoryCard(kind=CardKind.CHARACTER,name="同名",notes="未选择的角色资料",sceneIds=listOf(c.scene.id));val hidden=StoryCard(kind=CardKind.OUTLINE,name="未来剧情秘密",sceneIds=listOf(future.scene.id));val r=StoryRelation(fromId=a.id,toId=b.id,label="兄弟",sceneIds=listOf(c.scene.id));val book=Book("fixture","合成",listOf(c,future),style="旧风格",facts="旧事实",cards=listOf(a,b,hidden),relations=listOf(r));val anchor=selectionAnchor(c,2,4);val plain=selectionRequest(book,c,anchor,"润色","轻");assertEquals("选区",plain.passage);assertEquals("",plain.facts);assertEquals("",plain.style);val scoped=selectionRequest(book,c,anchor,"润色","轻",setOf(a.id),setOf(r.id));assertTrue(scoped.facts.contains(a.id));assertTrue(scoped.facts.contains(b.id));assertFalse(scoped.facts.contains(b.notes));assertFalse(scoped.facts.contains(hidden.name));assertFalse(scoped.facts.contains("旧事实"));assertFalse(scoped.facts.contains("后文"));assertThrows(IllegalArgumentException::class.java){selectionRequest(book,c,anchor,"润色","轻",setOf(hidden.id))}}
 @Test fun automaticRecoveryInvalidatesEarlierAnchors(){val root=Files.createTempDirectory("story-epoch").toFile();try{val s=Store(root);val original=s.importBook("合成.txt","原文".toByteArray());val anchor=selectionAnchor(original.chapters[0],0,2);s.editSelection(original.id,anchor,"新文");java.io.File(root,"${original.id}/book.json").writeText("corrupt");val recovered=s.load(original.id)!!;assertEquals("原文",recovered.chapters[0].text);assertFalse(anchor.matches(recovered.chapters[0]));assertThrows(IllegalArgumentException::class.java){s.editSelection(original.id,anchor,"旧候选")};assertEquals(recovered,s.load(original.id))}finally{root.deleteRecursively()}}
 @Test fun rollbackOfRemovedChapterNeverRevivesOldAnchor(){val root=Files.createTempDirectory("story-rollback-epoch").toFile();try{val s=Store(root);val b=s.importBook("合成.txt","原文".toByteArray());val a=selectionAnchor(b.chapters[0],0,2);s.save(b.copy(chapters=listOf(Chapter("替代章","其他"))));val restored=s.rollback(b.id,s.revisions(b.id).first());assertEquals(b.chapters[0].id,restored.chapters[0].id);assertFalse(a.matches(restored.chapters[0]));assertThrows(IllegalArgumentException::class.java){s.editSelection(b.id,a,"旧候选")}}finally{root.deleteRecursively()}}
 @Test fun repeatedSceneReferencesRejectedBeforeExpensiveValidation(){val c=Chapter("章","正文");val b=Book("fixture","合成",listOf(c),cards=listOf(StoryCard(kind=CardKind.CHARACTER,name="人物",sceneIds=listOf(c.scene.id,c.scene.id))));assertThrows(IllegalArgumentException::class.java){StoryJson.validate(b)};assertThrows(IllegalArgumentException::class.java){StoryJson.strings(org.json.JSONArray(List(5001){"scene"}))}}
}
